<script setup lang="ts">
import {computed,onMounted,ref} from 'vue';
import {getSession,refreshCsrf,logout} from '../FleetAndDocuments/api';
import type {Session} from '../FleetAndDocuments/contracts';
import {request,failure,ApiError} from '../Administration/api';
import InventoryPanel from './InventoryPanel.vue';
import PurchasesPanel from './PurchasesPanel.vue';
import type {Intent} from './contracts';
import '../Workshop/workshop.css';
const session=ref<Session|null>(null),booting=ref(true),busy=ref(false),error=ref(''),success=ref(''),errors=ref<Record<string,string[]>>({}),epoch=ref(0),pending=ref<Intent|null>(null),expired=ref(false);
const recovery=new Map<string,Intent>();
const purchasing=window.location.pathname.startsWith('/compras'),admin=computed(()=>session.value?.roles.includes('administrator')??false),office=computed(()=>session.value?.roles.some(r=>['administrator','secretary'].includes(r))??false),allowed=computed(()=>office.value||(!purchasing&&session.value?.roles.includes('mechanic')));
async function inspect():Promise<void>{try{session.value=await getSession();pending.value=recovery.get(session.value.id)??null;}catch(e){session.value=null;report(e);}finally{booting.value=false;}}
async function report(e:unknown):Promise<void>{const v=failure(e);error.value=v.message;errors.value=v.fields;expired.value=v.status===419;if(v.status===401)session.value=null;if(v.status===403){try{session.value=await getSession();pending.value=recovery.get(session.value.id)??null;}catch{session.value=null;}}}
async function send(intent:Intent):Promise<void>{if(busy.value)return;busy.value=true;error.value='';success.value='';errors.value={};let attempted=false;const recovering=recovery.has(intent.actor);try{const current=await getSession();session.value=current;pending.value=recovery.get(current.id)??null;if(current.id!==intent.actor||current.roles.slice().sort().join('|')!==intent.roles.slice().sort().join('|'))throw new ApiError(403,'La identidad o los permisos cambiaron. Consulta el estado con la cuenta y permisos originales.');attempted=true;await request(intent.path,'POST',intent.body);recovery.delete(intent.actor);pending.value=null;success.value='Operación confirmada. Los datos se actualizan desde el servidor.';epoch.value++;}catch(e){const v=failure(e);await report(v);if(recovering || (attempted&&(v.status===0||v.status>=500||v.status===419))){recovery.set(intent.actor,intent);if(session.value?.id===intent.actor)pending.value=intent;}else if(attempted){recovery.delete(intent.actor);pending.value=null;}}finally{busy.value=false;}}
async function command(title:string,path:string,body:Record<string,unknown>):Promise<void>{if(busy.value||pending.value||!session.value)return;if(!window.confirm(`${title}. ¿Confirmas los datos y la operación?`))return;await send({actor:session.value.id,roles:[...session.value.roles],title,path,body:{...body,request_key:crypto.randomUUID()}});}
async function retry():Promise<void>{if(pending.value&&session.value?.id===pending.value.actor&&!busy.value&&window.confirm('Reenviar exactamente la operación pendiente con su misma clave.'))await send(pending.value);}
async function refresh():Promise<void>{try{await refreshCsrf();expired.value=false;await inspect();}catch(e){report(e);}}
async function exit():Promise<void>{if(pending.value||busy.value)return;try{await logout();session.value=null;}catch(e){report(e);}}
function guardNavigation(event:MouseEvent):void{const target=event.target;if((busy.value||pending.value)&&target instanceof Element&&target.closest('a'))event.preventDefault();}
onMounted(inspect);
</script>
<template><main @click.capture="guardNavigation" class="administration-shell min-h-screen bg-blue-50 text-slate-900"><header class="bg-white border-b border-blue-200 p-5"><div class="max-w-7xl mx-auto flex flex-wrap justify-between gap-4"><div><p class="text-blue-700 font-semibold">Transportes Líquidos</p><h1 class="text-2xl font-bold">{{purchasing?'Compras de repuestos':'Inventario operativo'}}</h1><p v-if="session">{{session.login}}</p></div><nav aria-label="Navegación de Inventario y Compras" class="flex flex-wrap gap-3"><a href="/taller">Taller</a><a v-if="office" href="/inventario">Inventario</a><a v-if="office" href="/compras">Compras</a><a v-if="office" href="/transporte">Transporte</a><a v-if="admin" href="/administracion/catalogos">Administración</a><button v-if="session" :disabled="busy||!!pending" @click="exit">Cerrar sesión</button></nav></div></header><div class="max-w-7xl mx-auto p-4 md:p-6 space-y-5"><p v-if="booting" role="status">Consultando sesión…</p><p v-if="error" role="alert" class="notice-error">{{error}}</p><ul v-if="Object.keys(errors).length" role="alert" class="notice-error"><template v-for="(messages,key) in errors" :key="key"><li v-for="message in messages" :key="message">{{key}}: {{message}}</li></template></ul><p v-if="success" role="status" class="notice-success">{{success}}</p><button v-if="expired" class="btn-secondary" :disabled="busy" @click="refresh">Actualizar sesión de seguridad</button><section v-if="pending&&session?.id===pending.actor&&allowed" class="panel space-y-3"><h2 class="font-semibold">Operación pendiente de confirmación</h2><p>No se asume que falló. Se conserva en memoria el contenido y la clave original. Consulta los registros o reenvía esta misma operación; no hay reintentos automáticos.</p><p>{{pending.title}}</p><button class="btn-secondary" :disabled="busy" @click="retry">Reintentar la misma operación</button></section><section v-if="!booting&&!session" class="panel"><p>Inicia sesión en el sistema para continuar.</p><a href="/taller" class="btn-primary">Ir al inicio de sesión</a><button class="btn-secondary" @click="inspect">Comprobar sesión</button></section><p v-else-if="!booting&&!allowed" role="alert">No tienes acceso a este módulo.</p><PurchasesPanel :key="`${session?.id}:${session?.roles.join('|')}`" v-else-if="!booting&&purchasing" :admin="admin" :busy="busy||!!pending" :epoch="epoch" @command="command" @error="report"/><InventoryPanel :key="`${session?.id}:${session?.roles.join('|')}`" v-else-if="!booting" :admin="admin" :office="office" :busy="busy||!!pending" :epoch="epoch" @command="command" @error="report"/></div></main></template>
<style scoped>
.administration-shell :deep(.panel){background:white;border:1px solid #bfdbfe;border-radius:.75rem;padding:1.25rem}.administration-shell :deep(.field){display:block;width:100%;border:1px solid #94a3b8;border-radius:.375rem;padding:.65rem;margin:.3rem 0}.administration-shell :deep(.btn-primary),.administration-shell :deep(.btn-secondary){display:inline-block;border-radius:.375rem;padding:.65rem 1rem;cursor:pointer}.administration-shell :deep(.btn-primary){background:#1d4ed8;color:white}.administration-shell :deep(.btn-secondary){background:#eff6ff;color:#1e40af;border:1px solid #93c5fd}.administration-shell :deep(button:disabled){opacity:.5;cursor:wait}.administration-shell :deep(.data-table){width:100%;border-collapse:collapse}.administration-shell :deep(th),.administration-shell :deep(td){padding:.75rem;text-align:left;border-bottom:1px solid #dbeafe}.administration-shell :deep(th){background:#eff6ff}.administration-shell :deep(.notice-info),.administration-shell :deep(.notice-success),.administration-shell :deep(.notice-error){border-radius:.375rem;padding:1rem}.administration-shell :deep(.notice-info){background:#dbeafe}.administration-shell :deep(.notice-success){background:#dcfce7}.administration-shell :deep(.notice-error){background:#fee2e2;color:#991b1b}nav a{color:#1d4ed8;text-decoration:underline}label{display:block}
</style>
